(() => {
  const completionKey = id => `sams-canvas.tour.v1.${id}`;
  const pendingKey = id => `sams-canvas.tour.pending.v1.${id}`;
  let root = null, current = 0, retryTimer = 0;
  const steps = [
    { eyebrow:'YOUR CREATIVE FLOW', title:'From first spark to finished story.', copy:'Sam’s Canvas keeps the whole process in one place. Start with the content you want to make, collect ideas on its whiteboard, plan each shot, then set a day for it.', art:`<div class="tour-flow"><div class="tour-flow-card"><i class="tour-icon">${icon('play')}</i><b>Content</b><small>Give the idea a name</small></div><span class="tour-flow-wire"></span><div class="tour-flow-card"><i class="tour-icon">${icon('board')}</i><b>Whiteboard</b><small>Gather and connect ideas</small></div><span class="tour-flow-wire"></span><div class="tour-flow-card"><i class="tour-icon">${icon('camera')}</i><b>Shot sequencer</b><small>Shape the recording</small></div><span class="tour-flow-wire"></span><div class="tour-flow-card"><i class="tour-icon">${icon('calendar')}</i><b>Calendar</b><small>Choose the day</small></div></div>` },
    { eyebrow:'01 · START WITH CONTENT', title:'Give your next idea a home.', copy:'Choose New content, add a title and a short description, then pick a platform and video or picture. Your new content card is ready to plan.', art:`<div class="tour-scene tour-create-scene"><div class="tour-mini-form"><div class="tour-mini-form-head"><span class="tour-platform-icon">▶</span><span>NEW CONTENT</span><span class="tour-mini-dots">•••</span></div><b>Why cozy games feel like home</b><div class="tour-mini-desc">A story about finding a place to belong.</div><div class="tour-mini-chips"><span>YouTube</span><span>Video</span></div><div class="tour-mini-button">+ &nbsp; Create content</div></div><div class="tour-cursor tour-cursor-click"><svg viewBox="0 0 28 34"><path d="M3 2v23l6-6 4 11 5-2-4-10 9 1Z"/></svg><small>click to create</small></div></div>` },
    { eyebrow:'02 · CONNECT A PUBLISHING DAY', title:'Give the story a date.', copy:'Drag a content card’s socket to a day in the publishing patchbay. When the socket lights up, let go to connect it. The Content Calendar shows the month at a glance.', art:`<div class="tour-scene tour-connect-scene"><div class="tour-connect-card"><i class="tour-socket"></i><small>YOUTUBE · VIDEO</small><b>Why cozy games feel like home</b><span>A story about finding a place to belong.</span></div><svg class="tour-connect-wire" viewBox="0 0 250 130" preserveAspectRatio="none"><path class="tour-wire-base" d="M2 64 C75 64 90 65 148 65 S190 65 237 65"/><path class="tour-wire-dash" d="M2 64 C75 64 90 65 148 65 S190 65 237 65"/></svg><div class="tour-date-machine"><small>PUBLISHING PATCHBAY</small><div class="tour-date-card"><span>THU</span><b>12</b><i></i><em>OPEN SLOT</em></div><div class="tour-date-card selected"><span>FRI</span><b>13</b><i></i><em>READY TO CONNECT</em></div><div class="tour-date-card"><span>SAT</span><b>14</b><i></i><em>OPEN SLOT</em></div></div><div class="tour-spark">✦</div><div class="tour-cursor tour-cursor-pull"><svg viewBox="0 0 28 34"><path d="M3 2v23l6-6 4 11 5-2-4-10 9 1Z"/></svg><small>drag to connect</small></div></div>` },
    { eyebrow:'03 · MAKE SPACE TO THINK', title:'Collect the pieces on your whiteboard.', copy:'Add notes, text, images and links, then arrange them freely. Drag between sockets to connect related thoughts. Drag empty space to pan; use the wheel to zoom.', art:`<div class="tour-scene tour-board-scene"><div class="tour-board-grid"></div><svg class="tour-board-wire" viewBox="0 0 520 260"><path d="M116 123 C177 123 176 73 233 73 S303 132 363 132"/></svg><div class="tour-board-note"><small>A LITTLE THOUGHT</small><b>Find the feeling<br>before the facts.</b><span>Opening angle →</span><i></i></div><div class="tour-board-reference"><div class="tour-board-image">${icon('image')}</div><b>Visual direction</b><small>A quiet world, warm light.</small><i></i></div><div class="tour-board-text"><small>STORY NOTES</small><b>What makes it feel like home?</b><span>• familiar rituals<br>• a place to return to</span></div><div class="tour-pan-hint">SPACE + DRAG TO PAN <span>↔</span></div></div>` },
    { eyebrow:'04 · EDIT THE CONNECTIONS', title:'Cut a wire when plans change.', copy:'On the whiteboard or Content tab, right-click and drag across a wire to cut it. You can also select the knife tool and draw across the connection.', art:`<div class="tour-scene tour-cut-scene"><div class="tour-cut-card">CONTENT<i></i></div><svg class="tour-cut-wire" viewBox="0 0 380 110"><path class="tour-cut-wire-left" d="M2 55 H148"/><path class="tour-cut-wire-right" d="M231 55 H378"/><path class="tour-cut-wire-ghost" d="M148 55 H231"/></svg><div class="tour-cut-card right">PUBLISH DAY<i></i></div><div class="tour-knife-art"><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M9 10 54 51 43 54 24 36 18 30 9 10Z"/><path d="m18 30 25 24"/></svg></div><div class="tour-cut-flash">✳</div><div class="tour-cut-hint">RIGHT-DRAG ACROSS THE WIRE</div></div>` },
    { eyebrow:'05 · PLAN THE RECORDING', title:'Turn the idea into a sequence.', copy:'Open Shot Sequencer and choose a content. Add one shot for each beat you want to record. Click a stamp when a take is recorded; right-click a stamp to clear it.', art:`<div class="tour-scene tour-shots-scene"><div class="tour-shot-film"><div class="tour-film-rail"></div><div class="tour-shot-film-title"><span>SHOT SEQUENCER</span><b>Why cozy games feel like home</b><small>2 / 3 recorded</small></div><div class="tour-shot-row"><span>01</span><div><small>SHOT 01 · OPENING</small><b>Open on a rainy Sunday and a familiar game.</b></div><i class="tour-recorded">✓</i></div><div class="tour-shot-row"><span>02</span><div><small>SHOT 02 · THE SHIFT</small><b>Explore the move from competition to comfort.</b></div><i class="tour-recorded">✓</i></div><div class="tour-shot-row current"><span>03</span><div><small>SHOT 03 · CLOSE</small><b>Finish on the feeling of belonging.</b></div><i class="tour-stamp">${icon('stamp')}</i></div></div><div class="tour-film-caption">PLAN EACH BEAT · RECORD AT YOUR PACE</div></div>` },
    { eyebrow:'06 · FIND YOUR LINEUP', title:'See the whole month, at a glance.', copy:'The Content Calendar puts your planned stories in a simple month grid. Open any content from its card, mark it posted, or move it to another day.', art:`<div class="tour-scene tour-calendar-scene"><div class="tour-calendar"><div class="tour-calendar-head"><span>YOUR CONTENT CALENDAR</span><b>A MONTH AT A GLANCE</b></div><div class="tour-calendar-grid"><span>MON</span><span>TUE</span><span>WED</span><span>THU</span><span>FRI</span><span>SAT</span><span class="sun">SUN</span><i></i><i></i><i></i><i></i><i></i><i></i><i class="sun"><b>08</b></i><i><b>09</b></i><i><b>10</b></i><i><b>11</b></i><i class="planned"><b>12</b><small>Why cozy games feel like home</small></i><i><b>13</b></i><i class="sun"><b>14</b></i><i><b>15</b></i><i><b>16</b></i><i><b>17</b></i><i><b>18</b></i><i class="planned"><b>19</b><small>A slower desk setup</small></i><i><b>20</b></i></div></div></div>` }
  ];
  function icon(name) {
    const paths = { play:'<path d="m8 5 11 7-11 7z"/>', board:'<rect x="3" y="4" width="18" height="15" rx="2"/><path d="m8 19-3 3m11-3 3 3M7 9h10m-10 4h7"/>', camera:'<path d="M4 8h4l2-3h5l2 3h3a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2Z"/><circle cx="12" cy="14" r="3"/>', calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h3m-3 3h3"/>', image:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="9" cy="10" r="2"/><path d="m21 15-5-5L5 20"/>', stamp:'<path d="M8 14h8l-1-4V7a3 3 0 0 0-6 0v3zM5 14h14v5H5zM4 22h16"/>' };
    return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`;
  }
  const accountId = user => user?.id || window.cloudSession?.user?.id || '';
  function markDone(id) { if (!id) return; localStorage.setItem(completionKey(id), '1'); localStorage.removeItem(pendingKey(id)); }
  function queueForAccount(user) { const id = accountId(user); if (id && !localStorage.getItem(completionKey(id))) localStorage.setItem(pendingKey(id), '1'); }
  function openIfPending() {
    const id = accountId(window.cloudSession?.user);
    if (!id || localStorage.getItem(completionKey(id)) || !localStorage.getItem(pendingKey(id))) return;
    if (document.documentElement.dataset.welcome !== 'closed' || root) return;
    const modalBackdrop = document.getElementById('modalBackdrop');
    if (modalBackdrop && !modalBackdrop.classList.contains('hidden')) { clearTimeout(retryTimer); retryTimer = setTimeout(openIfPending, 450); return; }
    open({ accountId:id, onboarding:true });
  }
  function open({ accountId:id = accountId(window.cloudSession?.user), onboarding=false } = {}) {
    if (root) return;
    current = 0; root = document.createElement('div'); root.className = 'creator-tour-backdrop';
    root.innerHTML = `<section class="creator-tour" role="dialog" aria-modal="true" aria-labelledby="creatorTourTitle"><header class="creator-tour-head"><div class="creator-tour-brand"><span class="creator-tour-mark">S</span><span>Sam’s Canvas<small>${onboarding?'A QUICK FIRST LOOK':'INTERACTIVE TOUR'}</small></span></div><button class="creator-tour-close" type="button" aria-label="Skip tutorial">×</button></header><div class="creator-tour-art" aria-hidden="true"></div><div class="creator-tour-content"><div class="creator-tour-eyebrow"></div><h2 id="creatorTourTitle"></h2><p class="creator-tour-copy"></p></div><footer class="creator-tour-footer"><button type="button" class="creator-tour-skip">Skip tutorial</button><div class="creator-tour-progress" aria-label="Tutorial progress"></div><div class="creator-tour-nav"><button type="button" class="creator-tour-back">Back</button><button type="button" class="creator-tour-next">Next <span aria-hidden="true">→</span></button></div></footer></section>`;
    document.body.append(root); root.addEventListener('click',e=>{if(e.target===root)finish(true)}); root.querySelector('.creator-tour-close').onclick=()=>finish(true); root.querySelector('.creator-tour-skip').onclick=()=>finish(true); root.querySelector('.creator-tour-back').onclick=()=>render(current-1); root.querySelector('.creator-tour-next').onclick=()=>current===steps.length-1?finish(false):render(current+1); root._accountId=id; root._onboarding=onboarding; document.addEventListener('keydown',onKeyDown); render(0); requestAnimationFrame(()=>root?.querySelector('.creator-tour-next')?.focus({preventScroll:true}));
  }
  function render(index) {
    if (!root) return; current=Math.max(0,Math.min(steps.length-1,index)); const step=steps[current];
    root.querySelector('.creator-tour-art').innerHTML=step.art; root.querySelector('.creator-tour-eyebrow').textContent=step.eyebrow; root.querySelector('.creator-tour-content h2').textContent=step.title; root.querySelector('.creator-tour-copy').textContent=step.copy; root.querySelector('.creator-tour-progress').innerHTML=steps.map((_,i)=>`<i class="${i===current?'active':i<current?'done':''}"></i>`).join('');
    const back=root.querySelector('.creator-tour-back'); back.disabled=current===0; root.querySelector('.creator-tour-next').innerHTML=current===steps.length-1?'Finish <span aria-hidden="true">✓</span>':'Next <span aria-hidden="true">→</span>'; root.querySelector('.creator-tour-skip').textContent=current===steps.length-1?'Close tour':'Skip tutorial'; root.querySelector('.creator-tour-art').dataset.step=String(current);
  }
  function onKeyDown(e) { if (!root) return; if (e.key==='Escape') {e.preventDefault();finish(true)} else if(e.key==='ArrowRight')render(current+1); else if(e.key==='ArrowLeft')render(current-1); }
  function finish(skipped) {
    if (!root) return; const id=root._accountId; if(id&&root._onboarding)markDone(id); const closing=root; root=null; document.removeEventListener('keydown',onKeyDown); closing.classList.add('is-closing'); setTimeout(()=>closing.remove(),180);
    if(id&&skipped&&closing._onboarding&&typeof toast==='function')toast('Tour skipped. You can replay it anytime from Help or your avatar menu.');
  }
  window.CreatorTutorial={open:()=>open(),authenticated:queueForAccount,openIfPending};
})();
